function readStored(key){try{const values=JSON.parse(localStorage.getItem(key)||'[]');if(!Array.isArray(values))return [];const ids=key==='es-comp'?values.map(id=>findSpace(id)?.id||venues.find(v=>v.id===id)?.spaces[0].id).filter(Boolean):values.filter(id=>venues.some(v=>v.id===id));return [...new Set(ids)].slice(0,key==='es-comp'?4:100)}catch(e){return []}}
