function persist(){try{localStorage.setItem('es-saved',JSON.stringify(saved));localStorage.setItem('es-comp',JSON.stringify(comp))}catch(e){toast('Сохранение в браузере недоступно. Выбор сохранён до закрытия страницы.')}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function header(){const r=route();return `<header><div class="container header-inner"><a class="logo" href="#/" aria-label="EventSpace — главная"><i class="logo-mark"></i>Event<span>Space</span></a><span class="location">${ic('pin')}Минск</span><nav class="nav"><a class="${r==='/catalog'?'active':''}" href="#/catalog">Каталог площадок</a><a class="${r.startsWith('/cases')?'active':''}" href="#/cases">Кейсы мероприятий</a><a class="${r.startsWith('/journal')?'active':''}" href="#/journal">Журнал</a></nav><div class="header-actions"><a class="icon-btn compare-header" href="#/compare" aria-label="Сравнение">${ic('compare')}${comp.length?`<b class="count">${comp.length}</b>`:''}</a><a class="icon-btn" href="#/favorites" aria-label="Избранное">${ic('heart')}${saved.length?`<b class="count">${saved.length}</b>`:''}</a><a class="btn outline" href="#/owners">Разместить площадку ${ic('arrow')}</a><button class="icon-btn menu-btn" data-action="menu" aria-label="Открыть меню">${ic('menu')}</button></div></div></header>`}
function footer(){return `<footer><div class="container"><div class="footer-main"><div><a class="logo" href="#/"><i class="logo-mark"></i>Event<span>Space</span></a><p>Хорошие события начинаются<br>с подходящего места.</p><p style="margin-top:18px">Минск, Беларусь · BYN</p></div><div class="footer-col"><strong>Найти своё место</strong><a href="#/catalog">Каталог площадок</a><a href="#/cases">Кейсы мероприятий</a><a href="#/journal">Журнал</a><a href="#/favorites">Избранное</a><a href="#/compare">Сравнение</a></div><div class="footer-col"><strong>Владельцам</strong><a href="#/owners">Разместить площадку</a><a href="#/pricing">Тарифы и продвижение</a><a href="#/contacts">Сотрудничество</a></div><div class="footer-col"><strong>EventSpace</strong><a href="#/about">О проекте</a><a href="#/contacts">Контакты</a><a href="#/design">Дизайн-система</a><a href="#/states">Состояния интерфейса</a></div></div><div class="footer-bottom"><span>© 2026 EventSpace · Дизайн-прототип. Все предложения вымышлены.</span><a href="#/legal/privacy">Политика конфиденциальности</a><a href="#/legal/terms">Условия использования</a></div></div></footer>`}
function card(v){const r=preferredSpace(v);if(!r)return '';const count=v.spaces.length;return `<article class="venue-card"><div class="card-photo"><a href="#/venue/${v.id}">${image(r.photo,v.name+' · '+r.name)}</a>${v.top?'<span class="badge ad">TOP · Реклама</span>':v.new?'<span class="badge">Новое место</span>':''}<button class="icon-btn ${saved.includes(v.id)?'selected':''}" data-action="favorite" data-id="${v.id}" aria-label="${saved.includes(v.id)?'Удалить из избранного':'Добавить в избранное'}" aria-pressed="${saved.includes(v.id)}">${ic('heart')}</button><span class="space-count-badge">${count} ${count===1?'пространство':count<5?'пространства':'пространств'}</span></div><div class="card-body"><div class="card-sub">${ic('pin')}${v.city} · ${v.district}${v.city==='Минск'?' район':''}</div><a href="#/venue/${v.id}"><h3>${v.name}</h3></a><div class="card-space-choice"><span>${hasSpaceFilters()&&matchingSpaces(v).length?'Под ваш запрос':'Пространство площадки'}</span><a href="${spaceUrl(r)}">${r.name}${ic('arrow')}</a></div><div class="card-tags"><span>${ic('guests')}до ${r.capacity} гостей</span><span>${r.area} м²</span><span>${r.type}</span></div><div class="card-bottom"><span class="price">от ${r.price} <small>BYN / час</small></span><a class="card-link" href="#/venue/${v.id}">Площадка ${ic('arrow')}</a></div><div class="card-links"><small>Цена и вместимость этого пространства</small><button class="compare-btn ${comp.includes(r.id)?'on':''}" data-action="compare" data-id="${r.id}" aria-pressed="${comp.includes(r.id)}">${ic(comp.includes(r.id)?'check':'compare')}${comp.includes(r.id)?'В сравнении':'Сравнить зал'}</button></div></div></article>`}
function caseCard(c){const v=venue(c.venue);return `<article class="case-card"><a href="#/cases/${c.id}"><div class="case-photo">${image(c.photo,c.name)}</div><span class="badge">${c.event} · ${c.guests} гостей</span><h3>${c.name}</h3></a><p>${v.name} · ${v.spaces[0].name}</p><a class="card-link" href="#/cases/${c.id}">Посмотреть кейс ${ic('arrow')}</a></article>`}
function articleCard(a){return `<article class="editor-card"><a href="#/journal/${a.id}">${image(a.photo,a.title)}<span class="eyebrow">${a.ad?'Реклама · ':''}${a.cat}</span><h3>${a.title}</h3><p>12 октября 2026 · ${a.time}</p></a></article>`}
function sectionHead(title,sub='',link='',label='Смотреть все'){return `<div class="section-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${link?`<a href="${link}">${label} ↗</a>`:''}</div>`}
function searchForm(){return `<form class="searchbox searchbox-v2" id="home-search"><div class="searchfield"><label id="home-event-label">Тип мероприятия</label>${customSelect('home-events','events',eventTypes,homeSelection.events,'Любое событие',true,'home','event')}</div><div class="searchfield"><label id="home-city-label">Город</label>${customSelect('home-city','city',cities,homeSelection.city,'Любой город',false,'home','city')}</div><div class="searchfield guest-field"><label for="search-guests">Вместимость до</label><div class="guest-input-wrap"><input id="search-guests" name="guests" value="${esc(homeSelection.guests)}" placeholder="80" type="number" min="1" max="1000" inputmode="numeric"><span>гостей</span></div></div><button class="btn" type="submit">${ic('search')}Найти площадку</button></form>`}
function home(){return `<main class="editorial-home"><section class="container editorial-hero" aria-labelledby="home-title"><div class="editorial-stage"><div class="editorial-copy"><h1 id="home-title">Место для<br>ваших важных<br>моментов.</h1><p>Площадки и пространства для свадьбы, встречи или праздника в одном каталоге.</p><div class="editorial-smallprint">У каждого события — своё настроение.<br>У каждого места — своя история.</div></div><div class="editorial-visual" id="hero-slider" role="region" aria-roledescription="карусель" aria-label="Площадки для вдохновения">${heroMarkup()}</div></div><div class="home-search-panel"><div class="editorial-search-heading"><div><span class="eyebrow">НАЧНЁМ С ВАШЕЙ ИДЕИ</span><h2>Каким будет ваше событие?</h2></div><p>Выберите формат, город и вместимость.</p></div>${searchForm()}</div></section><section class="section"><div class="container">${sectionHead('Для какого события ищем?')}<div class="categories">${categories.map(([c,i])=>`<a class="category" href="#/catalog?event=${encodeURIComponent(c)}">${ic(i)}<span>${c}</span><small>${venues.filter(v=>v.spaces.some(r=>r.events.includes(c))).length} площадок</small></a>`).join('')}</div></div></section><section class="section soft"><div class="container">${sectionHead('Места, которые вдохновляют','Площадки с разным характером. Пространство внутри выбираете вы.','#/catalog','Весь каталог')}<div class="grid3">${venues.slice(0,3).map(card).join('')}</div></div></section><section class="section"><div class="container">${sectionHead('Не просто место. Настроение.','Подборки для больших и маленьких поводов.','#/journal','Все подборки')}<div class="grid2"><a class="collection" href="#/catalog?event=${encodeURIComponent('Свадьба')}">${image('orangerie','Светлое пространство среди зелени')}<div class="collection-copy"><span class="eyebrow" style="color:#fff">БЛИЖЕ К ПРИРОДЕ</span><h3>Праздник с видом на зелень</h3><p>Оранжереи, террасы и загородные пространства ↗</p></div></a><a class="collection" href="#/catalog?type=${encodeURIComponent('Лофт')}">${image('studio','Лофт для событий')}<div class="collection-copy"><span class="eyebrow" style="color:#fff">СО СВОИМ ХАРАКТЕРОМ</span><h3>Места для смелых идей</h3><p>Пространства, которые легко сделать своими ↗</p></div></a></div></div></section><section class="section soft"><div class="container"><div class="case-overview"><div><span class="eyebrow">КЕЙСЫ МЕРОПРИЯТИЙ</span><h2>Пространство оживает<br>вместе с событием.</h2><p>Один и тот же зал может стать местом камерного ужина, деловой встречи или большого праздника. В кейсах показываем оформление, расстановку и детали, которые помогут представить ваше событие.</p>${btn('Смотреть все кейсы','#/cases','light')}</div><div class="case-overview-photos"><a href="#/cases" aria-label="Посмотреть примеры оформления событий">${image('terrace','Иллюстрация оформления свадебного ужина')}</a><a href="#/cases" aria-label="Перейти к кейсам мероприятий">${image('party','Иллюстрация дружеского события')}</a></div></div></div></section><section class="section"><div class="container">${sectionHead('Журнал о хороших событиях','Идеи, полезные детали и немного вдохновения.','#/journal','Читать журнал')}<div class="grid3">${articles.slice(0,3).map(articleCard).join('')}</div></div></section><section class="section"><div class="container">${sectionHead('От идеи — к своему месту')}<div class="steps"><div><span class="step-num">01</span><h3>Расскажите о событии</h3><p>Выберите формат, город и вместимость пространства.</p></div><div><span class="step-num">02</span><h3>Найдите своих фаворитов</h3><p>Сохраните площадки и сравните конкретные залы по важным деталям.</p></div><div><span class="step-num">03</span><h3>Свяжитесь напрямую</h3><p>Обсудите пространство и условия с представителем площадки.</p></div></div></div></section><div class="container"><div class="owner-banner"><div><span class="eyebrow">ДЛЯ ВЛАДЕЛЬЦЕВ ПРОСТРАНСТВ</span><h2>У вашего места есть история.<br>Поможем её рассказать.</h2><p>Представьте площадку и её залы в одном каталоге.</p></div>${btn('Разместить площадку','#/owners','peach')}</div></div></main>`}
function pageTop(title,description='',crumb=''){return `<div class="page-top"><div class="breadcrumbs"><a href="#/">Главная</a><span>/</span>${crumb||title}</div><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>`}
function filterPanel(scope=''){const checkGroup=(title,vals)=>`<div class="filter-group"><label class="title">${title}</label>${vals.map(f=>`<label class="check"><input type="checkbox" data-filter="features" value="${f}" ${filters.features.includes(f)?'checked':''}>${f}</label>`).join('')}</div>`;return `<aside class="filter-panel"><div class="filter-panel-heading"><h3>${ic('filter')}Фильтры</h3><button class="text-btn" data-action="reset-filters">Сбросить</button></div><div class="filter-group"><label class="title">Город</label>${customSelect('filter-city'+scope,'city',cities,filters.city,'Любой город',false,'catalog')}</div><div class="filter-group"><label class="title">Тип мероприятия <small>несколько</small></label>${customSelect('filter-events'+scope,'events',eventTypes,filters.events,'Любое событие',true,'catalog')}</div><div class="filter-group"><label class="title">Тип пространства <small>несколько</small></label>${customSelect('filter-types'+scope,'types',venueTypes,filters.types,'Любое пространство',true,'catalog')}</div><div class="filter-group"><label class="title" for="guest-filter${scope}">Вместимость до</label><div class="guest-input-wrap bordered"><input id="guest-filter${scope}" class="input" data-filter="guests" type="number" min="1" max="1000" inputmode="numeric" placeholder="Любая" value="${esc(filters.guests)}"><span>гостей</span></div><small class="field-help">Пространства вместимостью не более указанного числа.</small></div><div class="filter-group"><label class="title" for="price-filter${scope}">До ${filters.price} BYN / час</label><input class="range" id="price-filter${scope}" aria-label="Максимальная цена за час" data-filter="price" type="range" min="50" max="500" step="10" value="${filters.price}"><small class="field-help">Стоимость выбранного пространства</small></div>${checkGroup('Оборудование',['Проектор','Звуковая система','Сцена'])}${checkGroup('Ваши условия',['Свой алкоголь','Свой кейтеринг'])}${checkGroup('Удобства',['Парковка','Wi-Fi','Терраса','Доступная среда'])}<button class="btn full filter-apply" data-action="close-filters">Показать площадки</button></aside>`}
function filteredVenues(){const vs=venues.filter(v=>matchingSpaces(v).length);if(sort==='cheap')vs.sort((a,b)=>preferredSpace(a).price-preferredSpace(b).price);else if(sort==='expensive')vs.sort((a,b)=>preferredSpace(b).price-preferredSpace(a).price);else if(sort==='capacity')vs.sort((a,b)=>preferredSpace(b).capacity-preferredSpace(a).capacity);else if(sort==='new')vs.sort((a,b)=>Number(!!b.new)-Number(!!a.new));else vs.sort((a,b)=>Number(!!b.top)-Number(!!a.top));return vs}
function activeChips(){let chips=[];for(const key of ['events','types'])filters[key].forEach(value=>chips.push(`<button class="chip active" data-action="remove-multi-filter" data-key="${key}" data-id="${esc(value)}">${esc(value)}${ic('close')}</button>`));for(const key of ['city','district','guests'])if(filters[key])chips.push(`<button class="chip active" data-action="remove-filter" data-key="${key}">${key==='guests'?'До '+esc(filters.guests)+' гостей':esc(filters[key])}${ic('close')}</button>`);if(filters.price<500)chips.push(`<button class="chip active" data-action="remove-filter" data-key="price">До ${filters.price} BYN${ic('close')}</button>`);filters.features.forEach(f=>chips.push(`<button class="chip active" data-action="remove-feature" data-id="${f}">${f}${ic('close')}</button>`));return chips.join('')}
function mapMarkup(vs){return `<div class="map"><svg class="map-art" viewBox="0 0 800 450" preserveAspectRatio="none" aria-hidden="true"><rect width="800" height="450" fill="#e9ecdf"/><path d="M-30 350 250 290 430 160 750 100 840 130" fill="none" stroke="#c1d1cc" stroke-width="38"/><path d="M100-10 170 160 350 220 550 450M0 100 190 170 390 100 800 300M10 430 210 360 490 340 800 370M400-20 360 170 260 460M650-10 620 190 730 450" stroke="#fafbf6" stroke-width="18" fill="none"/><path d="M100-10 170 160 350 220 550 450M0 100 190 170 390 100 800 300" stroke="#d5d9cc" stroke-width="1" fill="none"/><text x="360" y="260" font-family="Arial" font-size="24" fill="#98a28f">МИНСК</text><circle cx="70" cy="260" r="45" fill="#d6dfc6"/><circle cx="700" cy="50" r="70" fill="#d6dfc6"/></svg>${vs.map((v,i)=>`<button class="map-pin" style="left:${12+(i*19)%68}%;top:${18+(i*17)%60}%" data-action="map-preview" data-id="${v.id}">${preferredSpace(v).price} BYN</button>`).join('')}<span class="map-caption">Схема расположения · условные адреса, не для навигации</span><div id="map-preview"></div></div>`}
function catalog(){const vs=filteredVenues(),rooms=vs.reduce((n,v)=>n+matchingSpaces(v).length,0);return `<main class="container catalog-page">${pageTop('Найдите место для своей истории','Одна площадка — несколько возможностей. Выбирайте пространство по формату и деталям.','Каталог площадок')}<section class="catalog-command"><div class="catalog-search"><label for="catalog-query">${ic('search')}Найти площадку или пространство</label><input id="catalog-query" class="input" placeholder="Название, зал или формат пространства" value="${esc(filters.q)}"><span>${vs.length} площадок · ${rooms} пространств</span></div><div class="catalog-command-bottom"><button class="btn light mobile-filter" data-action="filters">${ic('filter')}Фильтры${hasSpaceFilters()?'<b class="filter-dot"></b>':''}</button><div class="catalog-sort"><span>Показать</span>${customSelect('catalog-sort','sort',[['recommended','Рекомендуемые'],['cheap','Сначала дешевле'],['expensive','Сначала дороже'],['capacity','Больше вместимость'],['new','Сначала новые']],sort,'Рекомендуемые',false,'sort')}</div><div class="segmented view-toggle" aria-label="Вид каталога"><button class="${!mapView?'active':''}" data-action="view-list" aria-pressed="${!mapView}">${ic('grid')}<span>Карточки</span></button><button class="${mapView?'active':''}" data-action="view-map" aria-pressed="${mapView}">${ic('pin')}<span>На карте</span></button></div></div></section><div class="catalog-layout">${filterPanel()}<div class="catalog-results"><div class="catalog-results-heading"><p>${vs.length} площадок · ${rooms} подходящих пространств</p><span>${ic('info')}Цена и вместимость относятся к одному залу</span></div><div class="chips">${activeChips()}</div>${vs.length?(mapView?mapMarkup(vs):`<div class="grid3">${vs.slice(0,showCount).map(card).join('')}</div>${showCount<vs.length?`<div class="pagination"><button class="btn light" style="width:auto" data-action="load-more">Показать ещё ${vs.length-showCount}</button></div>`:''}`):empty('search','Здесь пока тихо','Попробуйте увеличить вместимость, изменить город или убрать часть фильтров.','Сбросить фильтры','reset-filters')}</div></div></main>`}
function empty(icon,title,text,action,handler,url){return `<div class="empty"><span class="empty-symbol">${ic(icon)}</span><h2>${title}</h2><p>${text}</p>${url?btn(action,url):`<button class="btn" data-action="${handler}">${action}${ic('arrow')}</button>`}</div>`}
function contactBlock(v,r=null){const min=Math.min(...v.spaces.map(x=>x.price));return `<aside class="contact-card"><span class="eyebrow">${r?'АРЕНДА ПРОСТРАНСТВА':'ПЛОЩАДКА И ЕЁ ПРОСТРАНСТВА'}</span>${r?`<h3 class="contact-room-name">${r.name}</h3>`:`<h3 class="contact-room-name">${v.name}</h3>`}<div class="price">от ${r?r.price:min} <small>BYN / час</small></div><p>${r?'Стоимость этого пространства.':'Стоимость зависит от выбранного пространства.'}<br>Минимальная аренда — 3 часа.</p><button class="btn full" data-action="contact" data-id="${v.id}" ${r?`data-room="${r.id}"`:''}>${ic('phone')}Связаться с площадкой</button><button class="btn light full" data-action="contact-channel" data-channel="Telegram">${ic('send')}Написать в Telegram</button><button class="text-btn" data-action="contact-channel" data-channel="Сайт площадки">${ic('web')}Сайт площадки ↗</button><div class="contact-person"><span class="avatar">А</span><div>Анна · представитель<br><small>${v.company}</small></div></div><small class="contact-note">Уточните дату, пространство и итоговую стоимость у представителя.</small></aside>`}
function galleryFor(v){return ['Переговорная','Студия'].includes(v.type)?[v.photo,'studio','venue-loft',v.photo,'conference']:[v.photo,'terrace','hall','dinner',v.photo]}
function venuePage(id){const v=venues.find(x=>x.id===id);if(!v)return notFound();if(v.spaces.length===1)return spacePage(v.id,v.spaces[0].id,true);const matched=matchingSpaces(v),max=Math.max(...v.spaces.map(r=>r.capacity));return `<main class="detail-page"><div class="container"><div class="page-top"><div class="breadcrumbs"><a href="#/">Главная</a> / <a href="#/catalog">Площадки</a> / ${v.name}</div><div class="title-row"><div><span class="eyebrow">${v.spaces.length} ПРОСТРАНСТВА · ОДИН АДРЕС</span><h1>${v.name}</h1></div><button class="icon-btn ${saved.includes(id)?'selected':''}" data-action="favorite" data-id="${id}" aria-label="Сохранить площадку" aria-pressed="${saved.includes(id)}">${ic('heart')}</button></div><p class="venue-address">${ic('pin')}${v.address}${v.top?' <span class="badge ad">TOP · Реклама</span>':''}</p></div>${galleryMarkup(v)}<div class="venue-section-nav"><button data-action="scroll-section" data-id="venue-spaces">Пространства <b>${v.spaces.length}</b></button><button data-action="scroll-section" data-id="venue-about">О площадке</button><button data-action="scroll-section" data-id="venue-location">Расположение</button><button data-action="contact" data-id="${v.id}">Контакты${ic('arrow')}</button></div><div class="detail-layout"><div class="detail-content"><div class="facts"><div><strong>${v.spaces.length}</strong><small>пространства</small></div><div><strong>до ${max}</strong><small>гостей в одном варианте</small></div><div><strong>${v.city}</strong><small>город</small></div></div><section id="venue-spaces" class="venue-spaces-section"><span class="eyebrow">ВЫБЕРИТЕ СВОЁ ПРОСТРАНСТВО</span><h2>У каждого зала — свой характер</h2><p class="section-description">Сравните залы внутри площадки. У каждого — свои фотографии, вместимость, оборудование и условия.</p>${hasSpaceFilters()?`<div class="match-notice">${ic('filter')}${matched.length?'Под ваши условия подходит: '+matched.map(r=>r.name).join(', '):'Ни одно пространство не подходит под текущие фильтры. Ниже — все варианты площадки.'}</div>`:''}<div class="space-list">${v.spaces.map(r=>spaceCard(r,hasSpaceFilters()&&matched.some(x=>x.id===r.id))).join('')}</div></section><section id="venue-about"><h2>О площадке</h2><p>${v.desc||'Место с несколькими форматами для событий. Здесь можно подобрать пространство под ваш сценарий, число гостей и настроение.'}</p><p class="section-description">Компания-владелец: ${v.company}. Все перечисленные пространства находятся по одному адресу. По вопросам любого зала можно обратиться к общему представителю.</p></section><section><h2>Общая инфраструктура</h2><div class="amenities amenities-interactive">${v.commonFeatures.map((f,i)=>amenityItem(v,f,i)).join('')}</div><p class="amenities-hint below">Нажмите на пункт, чтобы уточнить детали. Оборудование каждого зала указано на его странице.</p></section><section id="venue-location"><h2>Расположение</h2><p class="section-description">${v.address}</p>${mapMarkup([v])}</section><section><h2>События на площадке</h2><div class="grid2">${cases.filter(c=>c.venue===id).map(caseCard).join('')||'<p>Истории этой площадки появятся здесь.</p>'}</div></section></div>${contactBlock(v)}</div><section class="section">${sectionHead('Другие места с характером','','#/catalog','В каталог')}<div class="grid3">${venues.filter(x=>x.id!==id).slice(0,3).map(card).join('')}</div></section></div>${mobileContact(v)}</main>`}
const amenityDetails={
  'Парковка':v=>`На территории — ${v.capacity>=150?30:18} парковочных мест. Есть зона для краткой остановки и разгрузки оборудования. Места для гостей согласуйте заранее.`,
  'Проектор':v=>v.id==='forum'?'Лазерный проектор Full HD, яркость 5 000 лм, экран шириной 4 м. Подключение по HDMI; переходник USB-C предоставляется. Настройка с техником по договорённости.':'Проектор Full HD (1920 × 1080), яркость 4 000 лм и экран 3 × 2 м. Подключение по HDMI, переходник USB-C предоставляется. Входит в аренду.',
  'Звуковая система':v=>v.id==='oran'?'Две активные акустические колонки, микшер и два беспроводных микрофона. Подключение ноутбука по кабелю. Базовый комплект входит в аренду; работа звукорежиссёра обсуждается отдельно.':'Две активные акустические колонки, микшерный пульт и два беспроводных микрофона. Есть линейный вход для ноутбука или DJ-пульта. Состав комплекта и техническое сопровождение согласуйте с представителем.',
  'Сцена':v=>`Модульный подиум ${v.capacity>=150?'6 × 4':'4 × 3'} м, высота 40 см. Расстановка и время монтажа согласуются заранее. Дополнительное сценическое освещение — по запросу.`,
  'Свой алкоголь':()=> 'Можно привезти свои напитки. Условия пробкового сбора, наличие бокалов и обслуживание уточняются при обсуждении мероприятия.',
  'Свой кейтеринг':()=> 'Можно пригласить свою кейтеринговую команду. Есть зона для подготовки и подключения оборудования. Время заезда, уборка и доступ к кухне согласуются заранее.',
  'Wi-Fi':()=> 'Отдельная гостевая сеть доступна в основном зале. Для видеотрансляции или большого числа подключений заранее уточните пропускную способность и возможность проводного подключения.',
  'Терраса':()=> 'Открытая зона со столиками и местами для отдыха. Может использоваться для приветственного фуршета или церемонии. Работа зависит от погоды; обогрев и навес уточняются отдельно.',
  'Доступная среда':()=> 'Предусмотрен вход без ступеней и широкий проход в основной зал. Наличие доступного санузла и удобного маршрута от парковки уточните у представителя перед визитом.',
  'Мебель для гостей':v=>`Столы и стулья для рассадки до ${v.capacity} гостей. Возможны банкетная, театральная и свободная схемы. Текстиль, декор и нестандартная мебель обсуждаются отдельно.`,
  'Естественное освещение':()=> 'В основном зале есть большие окна и дневной свет. Интенсивность зависит от времени суток и погоды. Для проекции и съёмки уточните возможность затемнения.'
};
function amenityItem(v,label,index){const id=`amenity-${v.id}-${index}`;const description=amenityDetails[label]?.(v)||'Подробности и условия использования уточните у представителя площадки.';const icon=label==='Мебель для гостей'?'guests':label==='Естественное освещение'?'leaf':featureIcon(label);return `<div class="amenity-item"><button type="button" class="amenity-trigger" data-action="amenity-info" aria-expanded="false" aria-controls="${id}" aria-describedby="${id}">${ic(icon)}<span>${esc(label)}</span>${ic('info','amenity-info-icon')}</button><span class="amenity-tip" id="${id}" role="tooltip" hidden><strong>${esc(label)}</strong><span>${esc(description)}</span><small>Демонстрационные сведения</small></span></div>`}
let amenityOpen=null,amenityCloseTimer;
function closeAmenity(){clearTimeout(amenityCloseTimer);if(!amenityOpen)return;amenityOpen.tip.hidden=true;amenityOpen.trigger.setAttribute('aria-expanded','false');amenityOpen=null}
function positionAmenity(trigger,tip){const rect=trigger.getBoundingClientRect(),box=tip.getBoundingClientRect(),gap=8,edge=12;const viewportWidth=document.documentElement.clientWidth,viewportHeight=window.innerHeight;tip.style.left=Math.max(edge,Math.min(rect.left,viewportWidth-box.width-edge))+'px';let top=rect.bottom+gap;if(top+box.height>viewportHeight-edge)top=rect.top-box.height-gap;tip.style.top=Math.max(edge,Math.min(top,viewportHeight-box.height-edge))+'px'}
function showAmenity(trigger,pinned=false){clearTimeout(amenityCloseTimer);if(amenityOpen?.trigger===trigger){amenityOpen.pinned=amenityOpen.pinned||pinned;return}closeAmenity();const tip=document.getElementById(trigger.getAttribute('aria-controls'));if(!tip)return;tip.hidden=false;trigger.setAttribute('aria-expanded','true');amenityOpen={trigger,tip,pinned};positionAmenity(trigger,tip)}
document.addEventListener('pointerover',e=>{if(e.pointerType==='touch')return;const item=e.target.closest('.amenity-item');if(!item)return;clearTimeout(amenityCloseTimer);if(!item.contains(e.relatedTarget))showAmenity(item.querySelector('.amenity-trigger'))});
document.addEventListener('pointerout',e=>{const item=e.target.closest('.amenity-item');if(!item||item.contains(e.relatedTarget)||!amenityOpen||amenityOpen.pinned)return;if(amenityOpen.trigger===document.activeElement&&amenityOpen.trigger.matches(':focus-visible'))return;amenityCloseTimer=setTimeout(closeAmenity,160)});
document.addEventListener('focusin',e=>{if(e.target.matches('.amenity-trigger:focus-visible'))showAmenity(e.target)});
document.addEventListener('focusout',e=>{if(amenityOpen?.trigger===e.target&&!e.target.closest('.amenity-item').contains(e.relatedTarget))closeAmenity()});
document.addEventListener('pointerdown',e=>{if(amenityOpen&&!amenityOpen.trigger.closest('.amenity-item').contains(e.target))closeAmenity()});
window.addEventListener('resize',closeAmenity);window.addEventListener('scroll',closeAmenity,{passive:true});
function featureIcon(f){return {'Парковка':'parking','Проектор':'screen','Звуковая система':'sound','Свой алкоголь':'wine','Свой кейтеринг':'food','Wi-Fi':'wifi','Терраса':'leaf','Сцена':'conference','Доступная среда':'guests'}[f]||'check'}
function comparePage(){const rs=comp.map(findSpace).filter(Boolean);const rows=[['Площадка',r=>r.venueName],['Город и район',r=>r.city+' · '+r.district],['Стоимость',r=>`от ${r.price} BYN / час`],['Вместимость',r=>`до ${r.capacity} гостей`],['Тип пространства',r=>r.type],['Площадь',r=>r.area+' м²'],['Парковка',r=>r.features.includes('Парковка')?'Есть':'Нет'],['Оборудование',r=>r.features.filter(f=>['Проектор','Звуковая система','Сцена'].includes(f)).join(', ')||'Не указано'],['Свой алкоголь',r=>r.features.includes('Свой алкоголь')?'Можно':'По согласованию'],['Свой кейтеринг',r=>r.features.includes('Свой кейтеринг')?'Можно':'Кейтеринг площадки'],['Удобства',r=>r.features.filter(f=>['Wi-Fi','Терраса','Доступная среда'].includes(f)).join(', ')||'Не указано'],['Кейсы',r=>r.cases+' кейс(ов)']];return `<main class="container">${pageTop('Детали, которые помогают выбрать','Сравнивайте конкретные пространства — даже если они находятся на одной площадке.','Сравнение пространств')}${!rs.length?empty('compare','Сначала — ваши варианты','Нажмите «Сравнить зал» в каталоге или на странице пространства. Можно выбрать от двух до четырёх вариантов.','Выбрать пространства',null,'#/catalog'):`<div class="toolbar compare-toolbar"><label class="check"><input class="toggle" id="differences" type="checkbox" ${differences?'checked':''}>Только различия</label><span>${rs.length} из 4 пространств</span><button class="text-btn" data-action="clear-compare">Очистить</button></div>${rs.length===1?'<p class="match-notice">Добавьте ещё одно пространство, чтобы сравнить условия.</p>':''}<div class="compare-scroll"><table class="compare-table"><thead><tr><th>Ваши варианты<small class="field-help">На телефоне прокрутите таблицу влево и вправо.</small>${rs.length<4?`<p style="margin-top:20px">${btn('Добавить','#/catalog','light small')}</p>`:''}</th>${rs.map(r=>`<th>${image(r.photo,r.name)}<div class="remove-compare"><h3><a href="${spaceUrl(r)}">${r.name}</a></h3><button class="text-btn" data-action="compare" data-id="${r.id}" aria-label="Убрать ${r.name}">${ic('close')}</button></div><a class="compare-venue-link" href="#/venue/${r.venueId}">${r.venueName}</a><div class="button-row">${btn('Подробнее',spaceUrl(r),'light small')}<button class="btn small" data-action="contact" data-id="${r.venueId}" data-room="${r.id}">Связаться</button></div></th>`).join('')}</tr></thead><tbody>${rows.filter(([label,f])=>!differences||new Set(rs.map(f)).size>1).map(([label,f])=>`<tr><td>${label}</td>${rs.map(r=>`<td class="${new Set(rs.map(f)).size>1?'diff':''}">${f(r)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}</main>`}
function favorites(){return `<main class="container">${pageTop('Места, к которым хочется вернуться','Сохраняйте понравившееся и выбирайте без спешки. Регистрация не нужна.','Избранное')}${saved.length?`<div class="toolbar"><p>Сохранено площадок: ${saved.length}</p><button class="text-btn" style="margin-left:auto" data-action="clear-favorites">Удалить все</button></div><div class="grid3">${saved.map(id=>card(venue(id))).join('')}</div><p style="font-size:11px;margin-top:25px">Избранное сохраняется в этом браузере.</p>`:empty('heart','Ваше место ещё впереди','Сохраняйте площадки с помощью сердечка. Они будут ждать вас здесь, в этом браузере.','Открыть каталог',null,'#/catalog')}</main>`}
function casesPage(){let cs=cases.filter(c=>(!caseFilter||c.event===caseFilter)&&(!caseGuests||(caseGuests==='small'?c.guests<=50:c.guests>50)));return `<main class="container">${pageTop('Так выглядят хорошие события','Вдохновляйтесь историями и смотрите, как пространство становится частью праздника.','Кейсы мероприятий')}<div class="chips">${['',...categories.map(x=>x[0])].map(x=>`<button class="chip ${caseFilter===x?'active':''}" data-action="case-filter" data-id="${x}">${x||'Все события'}</button>`).join('')}</div><div class="toolbar">${customSelect('case-guests','caseGuests',[['small','До 50 гостей'],['large','Больше 50 гостей']],caseGuests,'Любое количество гостей',false,'case')}<span class="demo-note">Иллюстративные истории и фотографии · не реальные мероприятия</span></div>${cs.length?`<div class="grid2">${cs.map(caseCard).join('')}</div>`:empty('camera','История ещё не написана','Для этого сочетания фильтров пока нет кейсов. Посмотрите другие форматы.','Все события','reset-cases')}</main>`}
function casePage(id){const c=cases.find(x=>x.id===id);if(!c)return notFound();const v=venue(c.venue);return `<main class="container">${pageTop(c.name,'',`<a href="#/cases">Кейсы мероприятий</a> / ${c.name}`)}<div class="case-meta"><span>${c.event}</span><span>${c.guests} гостей</span><a href="${spaceUrl(v.spaces[0])}">${ic('pin')} ${v.name} ↗</a><span class="badge">Иллюстративный кейс</span></div><div class="wide-photo">${image(c.photo,c.name)}</div><section class="section"><div class="reading"><span class="eyebrow">ИСТОРИЯ СОБЫТИЯ</span><h2>Когда место становится частью истории</h2><p class="intro" style="margin-top:25px">${c.desc}</p><h2>Пространство и детали</h2><p>Центром композиции стала общая зона для гостей. Декор выбрали спокойный: натуральный текстиль, небольшие цветочные композиции и тёплое освещение. Проходы оставили свободными, чтобы гостям и команде было удобно перемещаться.</p><div class="photo-grid">${image('dinner','Иллюстрация сервировки стола')}${image('hall','Иллюстрация оформления пространства')}</div><h2>Что помогло воплотить идею</h2><div class="amenities"><div>${ic('sound')}Звуковая система</div><div>${ic('screen')}Проектор для истории</div><div>${ic('guests')}Мобильная мебель</div><div>${ic('spark')}Дополнительный свет</div></div><blockquote>«Оставьте в пространстве место для общения — именно его гости запомнят лучше всего».</blockquote><small style="color:var(--muted)">Редакционная заметка для демонстрационного кейса.</small><div class="inline-venue">${image(v.photo,v.name)}<div><span class="eyebrow">МЕСТО ЭТОЙ ИСТОРИИ</span><h3>${v.name}</h3><p style="font-size:12px">До ${v.capacity} гостей · от ${v.price} BYN / час</p>${btn('Посмотреть пространство',spaceUrl(v.spaces[0]),'small')}</div></div>${demo}</div></section><section class="section">${sectionHead('Другие истории','','#/cases','Все кейсы')}<div class="grid3">${cases.filter(x=>x.id!==id).slice(0,3).map(caseCard).join('')}</div></section></main>`}
function journal(){const as=articles.filter(a=>(!journalFilter||a.cat===journalFilter)&&(!journalQuery||a.title.toLowerCase().includes(journalQuery.toLowerCase())));return `<main class="container">${pageTop('Журнал EventSpace','О местах, людях и событиях, ради которых стоит собраться.','Журнал')}<div class="toolbar"><div class="chips" style="margin:0">${['','Подборки площадок','Идеи мероприятий','Советы','Новости','Партнёрские материалы'].map(c=>`<button class="chip ${journalFilter===c?'active':''}" data-action="journal-filter" data-id="${c}">${c||'Все материалы'}</button>`).join('')}</div><input class="input" id="journal-query" value="${esc(journalQuery)}" placeholder="Найти в журнале" aria-label="Поиск по журналу"></div>${as.length?`${!journalFilter&&!journalQuery?`<a class="journal-hero" href="#/journal/choose">${image('orangerie',articles[0].title)}<div><span class="eyebrow">ВЫБОР РЕДАКЦИИ · СОВЕТЫ</span><h2>${articles[0].title}</h2><p>От первого впечатления до практичных деталей. На что смотреть, чтобы найти своё пространство.</p><span class="card-link">Читать материал ${ic('arrow')}</span><p style="font-size:11px;margin-top:25px">Редакция EventSpace · 12 октября 2026 · 7 минут</p></div></a>`:''}<div class="grid3">${(!journalFilter&&!journalQuery?as.slice(1):as).map(articleCard).join('')}</div>`:empty('search','Такого материала пока нет','Попробуйте другой запрос или откройте все материалы.','Все материалы','reset-journal')}<section class="section"><div class="feature-story"><div class="story-copy"><span class="eyebrow">ЧАЩЕ ЧИТАЮТ</span><h2>Сначала — правильные вопросы</h2><p>Небольшой список, который поможет подготовиться к разговору с владельцем.</p>${btn('12 вопросов о площадке','#/journal/checklist','outline')}</div>${image('studio','Светлое пространство для встреч')}</div></section><span class="demo-note">Демонстрационные редакционные материалы · иллюстративные фотографии</span></main>`}
function articlePage(id){const a=articles.find(x=>x.id===id);if(!a)return notFound();return `<main class="container"><div class="page-top"><div class="breadcrumbs"><a href="#/">Главная</a> / <a href="#/journal">Журнал</a> / ${a.cat}</div></div><div class="reading"><span class="eyebrow">${a.ad?'РЕКЛАМА · ПАРТНЁРСКИЙ МАТЕРИАЛ':a.cat}</span><h1>${a.title}</h1><div class="case-meta"><span>Редакция EventSpace</span><span>12 октября 2026</span><span>${a.time} чтения</span></div>${a.ad?'<div class="demo-note" style="margin-bottom:20px">Реклама · демонстрационный партнёр «Мануфактура». Реквизиты рекламодателя добавляются до публикации.</div>':''}</div><div class="wide-photo">${image(a.photo,a.title)}</div><section class="section"><article class="reading"><p class="intro">${a.intro||'У каждого пространства свой характер. Рассказываем, как заметить нужные детали и превратить идею в событие, которое будет приятно вспоминать.'}</p><h2>Начните не с адреса, а с ощущения</h2><p>Представьте вечер: кто рядом с вами, как звучит музыка, сидят ли гости за одним столом или свободно перемещаются по залу. Ответы помогут понять, какое пространство искать — светлую студию, уютную гостиную или большой зал со сценой.</p><p>Затем определите три опоры: формат мероприятия, примерное количество гостей и бюджет на аренду. Так вы сможете сравнивать площадки по одинаковым условиям.</p><h2>Посмотрите, как живёт пространство</h2><p>Фотографии пустого зала показывают архитектуру. Кейсы помогают увидеть масштаб, расстановку столов и реальное количество свободного места. Обратите внимание на проходы, дневное освещение и зоны для отдыха.</p><blockquote>Хорошая площадка помогает вашей идее стать яснее.</blockquote><div class="photo-grid">${image('garden','Пример торжественного оформления')}${image('dinner','Пример камерной сервировки')}</div><h2>Проверьте практичные детали</h2><p>Уточните, что входит в стоимость: мебель, оборудование, уборка, часы монтажа и демонтажа. Обсудите собственный кейтеринг, алкоголь и ограничения по шуму. Попросите показать зону разгрузки и вход для гостей.</p><div class="amenities"><div>${ic('check')}Итоговая стоимость</div><div>${ic('check')}Время подготовки</div><div>${ic('check')}Оборудование и мебель</div><div>${ic('check')}Правила и ограничения</div></div><h2>Место, с которого можно начать</h2><p>В каталоге удобно сохранить несколько вариантов и сравнить их по вместимости, цене и условиям. Например, вот пространство из нашей демонстрационной подборки.</p><div class="inline-venue">${image('orangerie','Оранжерея «Сад»')}<div><span class="eyebrow">СВЯЗАННАЯ ПЛОЩАДКА</span><h3>Оранжерея «Сад»</h3><p style="font-size:12px">До 120 гостей · от 150 BYN / час</p>${btn('Посмотреть','#/venue/oran','small')}</div></div><h2>И обязательно познакомьтесь лично</h2><p>Перед окончательным решением договоритесь о просмотре. Почувствуйте акустику, оцените свет и задайте владельцу оставшиеся вопросы. В EventSpace вы связываетесь с представителем напрямую и самостоятельно согласовываете условия.</p>${demo}<div style="margin-top:30px"><a class="card-link" href="#/journal">${ic('back')}Назад в журнал</a></div></article></section><section class="section">${sectionHead('Продолжить чтение')}<div class="grid3">${articles.filter(x=>x.id!==id).slice(0,3).map(articleCard).join('')}</div></section></main>`}
const planData=[{name:'FREE',price:0,tag:'Первое знакомство',desc:'Чтобы ваше пространство нашли',features:['До 5 фотографий','Краткое описание','Контакты и характеристики','1 кейс','Базовая статистика']},{name:'PRO',price:39,tag:'Больше возможностей',desc:'Чтобы рассказать о себе подробнее',features:['До 30 фотографий и видео','Подробное описание','До 5 кейсов','Специальные предложения','Расширенная аналитика','Дополнительное оформление']},{name:'TOP',price:99,tag:'Больше внимания',desc:'Чтобы быть заметнее в каталоге',features:['Всё из PRO','До 10 кейсов','Рекламное продвижение','Приоритетные рекламные позиции','Визуальное выделение','Рекламная статистика']}];
function plans(){return `<div class="plans">${planData.map((p,i)=>`<article class="plan ${i===1?'featured':''}">${i===1?'<span class="badge">Больше возможностей</span>':''}<span class="eyebrow" style="color:inherit">${p.name}</span><h3>${p.tag}</h3><div class="plan-price">${p.price}<small> BYN / мес.</small></div><p>${p.desc}</p><ul>${p.features.map(f=>`<li>${ic('check')}${f}</li>`).join('')}</ul><a class="btn full ${i===1?'peach':'outline'}" href="#/owners?plan=${p.name}">${i?'Выбрать '+p.name:'Начать бесплатно'}${ic('arrow')}</a></article>`).join('')}</div><p class="ad-label" style="margin-top:20px">Цены демонстрационные до окончательного утверждения. TOP-размещения явно помечаются как реклама.</p>`}
const faqs=[['Нужно ли регистрироваться для поиска?','Нет. Каталог, контакты, сравнение и избранное доступны без регистрации. Избранное и сравнение сохраняются в вашем браузере.'],['Можно ли забронировать площадку через EventSpace?','Вы выбираете площадку и связываетесь с владельцем напрямую. Доступность, условия аренды и расчёты обсуждаются с ним.'],['Как разместить свою площадку?','Оставьте короткую заявку. В рабочей версии сервиса команда свяжется с вами и поможет подготовить карточку. В этом прототипе форма только демонстрирует сценарий.'],['Можно ли начать бесплатно?','Да, для этого предусмотрен тариф FREE. Он включает основные сведения, контакты, до пяти фотографий и один кейс.'],['Что даёт рекламное продвижение?','Тариф TOP предусматривает рекламные позиции и визуальное выделение в каталоге. Такие карточки получают явную метку «TOP · Реклама».'],['Как изменить тариф?','В первой версии владельцы обращаются к команде сервиса через форму сотрудничества. Личный кабинет не предусмотрен.']];
function faqBlock(indices=[0,1,2,3]){return `<div class="faq">${indices.map(i=>`<details><summary>${faqs[i][0]}</summary><p>${faqs[i][1]}</p></details>`).join('')}</div>`}
function leadForm(plan='FREE'){return `<form class="form-panel demo-form" data-form="owner"><h3>Расскажите о вашем месте</h3><p style="font-size:12px;margin:-10px 0 22px">Интересует тариф: <strong>${esc(plan)}</strong>. Все поля со звёздочкой обязательны.</p><div class="field"><label for="venue-name">Название площадки *</label><input class="input" id="venue-name" name="venue" required placeholder="Например, Оранжерея «Сад»"></div><div class="field"><label for="person-name">Ваше имя *</label><input class="input" id="person-name" name="name" autocomplete="name" required placeholder="Как к вам обращаться"></div><div class="field"><label for="phone">Телефон *</label><input class="input" id="phone" name="phone" type="tel" autocomplete="tel" required pattern="[+0-9 ()-]{7,22}" placeholder="+375 (__) ___-__-__"></div><div class="field"><label for="contact">Email или Telegram *</label><input class="input" id="contact" name="contact" required placeholder="you@example.com или @username"></div><div class="field"><label for="site">Сайт или социальные сети</label><input class="input" id="site" name="site" placeholder="https://"></div><label class="check"><input type="checkbox" required><span>Согласен с <a href="#/legal/privacy" style="text-decoration:underline">политикой обработки данных</a></span></label><button type="submit" class="btn full">Отправить заявку ${ic('arrow')}</button><small style="color:var(--muted);display:block;margin-top:13px;font-size:10px">Демонстрационная форма: данные не отправляются и не сохраняются. Для проверки используйте условные сведения.</small></form>`}
function owners(){const qp=new URLSearchParams(route().split('?')[1]||'');let p=qp.get('plan')||'FREE';if(!['FREE','PRO','TOP'].includes(p))p='FREE';return `<main><div class="container"><div class="breadcrumbs" style="padding-top:30px"><a href="#/">Главная</a> / Владельцам площадок</div><section class="owner-hero"><div><span class="eyebrow">У ВАС ЕСТЬ МЕСТО. У НИХ — ПОВОД.</span><h1>Пусть о вашем<br>пространстве<br>узнают больше.</h1><p>Красиво расскажите о площадке и помогите будущим гостям увидеть в ней место для своего события.</p><button class="btn" data-action="scroll-application">Разместить бесплатно ${ic('arrow')}</button><p style="font-size:11px;margin-top:15px">Прямые обращения · Без комиссии с аренды</p></div><div class="owner-visual">${card(venues[0])}</div></section></div><section class="section soft"><div class="container">${sectionHead('Ваше пространство — в главной роли')}<div class="benefits"><div class="benefit">${ic('camera')}<h3>Покажите характер</h3><p>Фотографии, видео и кейсы расскажут о месте лучше длинного рекламного текста.</p></div><div class="benefit">${ic('guests')}<h3>Встретьте свою аудиторию</h3><p>Площадку найдут люди, которые уже выбирают место по формату, бюджету и числу гостей.</p></div><div class="benefit">${ic('phone')}<h3>Общайтесь напрямую</h3><p>Гости позвонят или напишут вам. Вы сами обсуждаете детали и условия аренды.</p></div></div></div></section><section class="section"><div class="container">${sectionHead('От заявки — к первым знакомствам')}<div class="steps"><div><span class="step-num">01</span><h3>Оставьте заявку</h3><p>Название, ваши контакты и ссылка на площадку.</p></div><div><span class="step-num">02</span><h3>Подготовим карточку</h3><p>Соберём фотографии, описание и важные характеристики.</p></div><div><span class="step-num">03</span><h3>Встречайте обращения</h3><p>Пользователи найдут ваши контакты в карточке.</p></div></div></div></section><section class="section soft"><div class="container"><div class="grid2"><div><span class="eyebrow">КОГДА ХОЧЕТСЯ БОЛЬШЕ</span><h2>Понимайте интерес.<br>Усиливайте продвижение.</h2><p style="margin-top:23px;max-width:490px">Следите за просмотрами и переходами к контактам. Используйте PRO для подробной презентации, а TOP — для отмеченных рекламных позиций.</p></div><div><span class="badge">Пример статистики · условные данные за месяц</span><div class="stats"><div class="stat"><strong>1 240</strong><small>просмотров</small></div><div class="stat"><strong>86</strong><small>открытий контактов</small></div><div class="stat"><strong>42</strong><small>сохранения</small></div></div><p style="font-size:11px;margin-top:18px">Иллюстрация будущей аналитики, не прогноз результатов.</p></div></div></div></section><section class="section"><div class="container">${sectionHead('Начните с того, что подходит вам','','#/pricing','Сравнить тарифы')}${plans()}</div></section><section class="section"><div class="container">${sectionHead('Остались вопросы?')}${faqBlock([2,3,4,5])}</div></section><section class="section soft" id="application"><div class="container form-layout"><div><span class="eyebrow">ДАВАЙТЕ ПОЗНАКОМИМСЯ</span><h2>Ваше место<br>заслуживает внимания.</h2><p style="margin-top:22px">Заполните короткую форму — это первый шаг к размещению.</p><p style="font-size:12px;margin-top:25px">В прототипе можно проверить валидацию и успешное завершение заявки.</p></div>${leadForm(p)}</div></section></main>`}
function pricing(){return `<main class="container">${pageTop('Больше возможностей для вашего места','От бесплатной карточки до рекламного продвижения. Выберите подходящий формат.','Тарифы')}<section style="padding:15px 0 35px">${plans()}</section><section class="section">${sectionHead('Все возможности рядом')}<div class="compare-scroll"><table class="spec-table" style="min-width:650px"><thead><tr><th>Возможность</th><th>FREE</th><th>PRO</th><th>TOP</th></tr></thead><tbody>${[['Фотографии','До 5','До 30','До 30'],['Видео','—','Да','Да'],['Описание','Краткое','Подробное','Подробное'],['Контакты и характеристики','Да','Да','Да'],['Кейсы','1','До 5','До 10'],['Специальные предложения','—','Да','Да'],['Оформление карточки','Базовое','Расширенное','С выделением'],['Аналитика','Базовая','Расширенная','С рекламной статистикой'],['Рекламное продвижение','—','—','Да, с маркировкой'],['Цена за месяц','0 BYN','39 BYN','99 BYN']].map(row=>`<tr>${row.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section><section class="section">${sectionHead('Перед первым шагом')}${faqBlock([3,4,5,2])}</section><div class="owner-banner"><div><h2>Не уверены, с чего начать?</h2><p>Расскажите о площадке. Подберём формат знакомства с аудиторией.</p></div>${btn('Обсудить размещение','#/owners','peach')}</div></main>`}
function about(){return `<main class="container">${pageTop('Места объединяют.','', 'О проекте')}<div class="about-quote serif">Мы помогаем найти пространство<br>для того, что важно вам.</div><div class="wide-photo">${image('garden','Люди собираются за праздничным столом')}</div><section class="section"><div class="about-grid"><div><span class="eyebrow">ЗАЧЕМ МЫ ЗДЕСЬ</span><h2>Меньше долгих поисков.<br>Больше предвкушения.</h2><p>Найти подходящую площадку бывает сложнее, чем придумать само событие. Фотографии разбросаны по соцсетям, условия неясны, а сравнивать приходится по памяти.</p><p>EventSpace собирает места, характеристики и контакты в одном каталоге. Начинаем с Минска и планируем постепенно знакомить вас с пространствами по всей Беларуси.</p></div>${image('studio','Светлый зал для встреч')}</div></section><section class="section soft" style="padding-left:28px;padding-right:28px;border-radius:17px">${sectionHead('Простые принципы')}<div class="benefits"><div class="benefit"><h3>Свобода выбора</h3><p>Публичный каталог и контакты доступны без регистрации. Вы выбираете в своём темпе.</p></div><div class="benefit"><h3>Прямой разговор</h3><p>Пользователи и владельцы общаются напрямую. Сервис помогает познакомиться.</p></div><div class="benefit"><h3>Понятные условия</h3><p>Вместимость и цена заметны сразу. Рекламные карточки получают отдельную маркировку.</p></div></div></section><section class="section"><div class="grid2"><div><h2>Для тех, кто собирает людей</h2><p style="margin:20px 0">Сохраняйте места, сравнивайте детали и смотрите примеры событий. Всё, чтобы сделать уверенный первый шаг.</p>${btn('Найти площадку','#/catalog','outline')}</div><div><h2>Для тех, у кого есть место</h2><p style="margin:20px 0">Покажите характер пространства, поделитесь кейсами и познакомьтесь с будущими гостями.</p>${btn('Рассказать о площадке','#/owners','outline')}</div></div></section>${demo}</main>`}
function contacts(){return `<main class="container">${pageTop('Давайте поговорим','Вопрос о сервисе, идея для журнала или предложение сотрудничества — мы открыты к разговору.','Контакты')}<div class="contact-grid"><div class="contact-info"><span class="eyebrow">НАПИШИТЕ НАМ</span><h3>Общие вопросы</h3><p class="serif">hello@eventspace.example</p><h3>Партнёрство и размещение</h3><p class="serif">partners@eventspace.example</p><p>Минск, Беларусь<br>Пн–пт, 10:00–18:00 (время Минска)</p><div class="demo-note">Контакты вымышлены, письма не доставляются.</div><p style="margin-top:25px">Чтобы обсудить конкретную площадку, воспользуйтесь контактами на её странице.</p></div><form class="form-panel demo-form" data-form="feedback"><h3>Обратная связь</h3><div class="field"><label for="feedback-name">Ваше имя *</label><input class="input" id="feedback-name" name="name" required autocomplete="name" placeholder="Как к вам обращаться"></div><div class="field"><label for="feedback-email">Email *</label><input class="input" id="feedback-email" name="email" type="email" required placeholder="you@example.com"></div><div class="field"><label for="feedback-message">Сообщение *</label><textarea class="input" id="feedback-message" name="message" required placeholder="Чем можем помочь?"></textarea></div><label class="check"><input type="checkbox" required><span>Согласен с <a href="#/legal/privacy" style="text-decoration:underline">политикой обработки данных</a></span></label><button class="btn full" type="submit">Отправить сообщение ${ic('arrow')}</button><small style="font-size:10px;color:var(--muted);display:block;margin-top:14px">Демонстрационная форма. Данные не отправляются и не сохраняются.</small></form></div><section class="section">${sectionHead('Возможно, ответ уже здесь')}${faqBlock([0,1,2,4])}</section></main>`}
function notFound(){return `<main class="container">${pageTop('Кажется, мы немного заблудились','', '404')}<div class="empty"><span class="serif" style="font-size:130px;line-height:1;color:#b4bba4">404</span><h2>У этой страницы другой адрес</h2><p>Возможно, ссылка устарела. Но ваше место для события точно найдётся.</p><div class="button-row">${btn('На главную','#/')} ${btn('Открыть каталог','#/catalog','outline')}</div></div></main>`}
function states(){const tabs=[['404','Страница 404'],['no-results','Нет результатов'],['loading','Загрузка'],['error','Ошибка формы'],['success','Заявка принята'],['favorites','Пустое избранное'],['compare','Пустое сравнение']];let content='';if(stateView==='404')content=notFound().replace('<main class="container">','<div>').replace('</main>','</div>');if(stateView==='no-results')content=empty('search','Пока ни одного совпадения','Попробуйте увеличить бюджет или убрать несколько фильтров. Ваши условия можно изменить в любой момент.','Изменить фильтры',null,'#/catalog');if(stateView==='favorites')content=empty('heart','Здесь будут ваши любимые места','Нажмите на сердечко в карточке, чтобы сохранить площадку без регистрации.','Найти своё место',null,'#/catalog');if(stateView==='compare')content=empty('compare','Посмотрим на детали вместе?','Добавьте от двух до четырёх площадок из каталога. Сравним цену, вместимость и условия.','Выбрать площадки',null,'#/catalog');if(stateView==='loading')content=`<div role="status" aria-label="Площадки загружаются"><p style="margin-bottom:20px">Ищем места для вашей истории…</p><div class="grid3">${[1,2,3].map(()=>`<div class="venue-card"><div class="skeleton" style="height:230px"></div><div style="padding:22px"><div class="skeleton" style="height:24px;width:80%;margin-bottom:17px"></div><div class="skeleton" style="height:14px;width:65%;margin-bottom:25px"></div><div class="skeleton" style="height:38px"></div></div></div>`).join('')}</div></div>`;if(stateView==='error')content=`<div class="form-panel" style="max-width:570px;margin:auto"><h3>Заявка на размещение</h3><div class="form-message error-message" role="alert">Не удалось отправить заявку. Ваши данные сохранены в полях — попробуйте ещё раз.</div><div class="field"><label>Название площадки</label><input class="input" value="Оранжерея «Сад»"></div><div class="field"><label>Телефон</label><input class="input" value="+375 (00) 000-00-00"></div><button class="btn full" data-action="retry">Попробовать снова ${ic('arrow')}</button><p style="font-size:11px;margin-top:14px">Макет ошибки сети. Повторная отправка покажет успешное состояние.</p></div>`;if(stateView==='success')content=empty('check','Спасибо! Мы познакомились.','В рабочем сервисе команда свяжется с вами для подготовки карточки. В прототипе заявка никуда не отправлена.','Вернуться на главную',null,'#/');return `<main class="container">${pageTop('Состояния, о которых мы позаботились','Служебные экраны и обратная связь в едином стиле.','Состояния интерфейса')}<div class="state-list">${tabs.map(([id,t])=>`<button class="chip ${stateView===id?'active':''}" data-action="state" data-id="${id}">${t}</button>`).join('')}</div><section style="background:white;border:1px solid var(--line);border-radius:16px;padding:22px">${content}</section><p style="font-size:11px;margin-top:20px">Состояния представлены отдельно для проверки макетов. Пустая выдача, избранное и сравнение также доступны в основном сценарии.</p></main>`}
function legal(kind){const privacy=kind==='privacy';return `<main class="container"><div class="reading legal">${pageTop(privacy?'Политика конфиденциальности':'Условия использования','Шаблон юридической страницы для последующей правовой проверки.','Правовая информация')}<div class="demo-note">Демонстрационный текст · не финальный юридический документ</div><h2>1. ${privacy?'Общие положения':'О сервисе'}</h2><p>${privacy?'Этот шаблон описывает структуру будущей политики обработки персональных данных. Перед запуском сюда необходимо добавить сведения об операторе, применимые основания обработки и порядок реализации прав субъектов данных.':'EventSpace — информационная платформа для поиска площадок. Пользователи самостоятельно связываются с владельцами и согласовывают условия проведения мероприятий.'}</p><h2>2. ${privacy?'Какие сведения обрабатываются':'Использование каталога'}</h2><p>${privacy?'В рабочем сервисе формы могут обрабатывать имя, контактные данные и сведения о площадке в целях ответа на обращение. В текущем демонстрационном прототипе содержимое форм не отправляется и не сохраняется.':'Каталог, избранное и сравнение доступны без регистрации. Все площадки, цены и контакты текущего прототипа вымышлены и служат для демонстрации интерфейса.'}</p><h2>3. ${privacy?'Локальное хранение':'Рекламные материалы'}</h2><p>${privacy?'Идентификаторы избранных и сравниваемых демонстрационных площадок сохраняются локально в браузере. Вы можете очистить их в соответствующих разделах или через настройки браузера.':'Рекламные площадки отмечены меткой «TOP · Реклама». Партнёрские статьи имеют явную маркировку. Итоговые условия рекламных размещений утверждаются отдельно.'}</p><h2>4. ${privacy?'Сроки, права и обращения':'Ответственность и контакты'}</h2><p>В финальной версии здесь будут указаны реквизиты оператора, порядок обращений и применимые сроки. Демонстрационный адрес: hello@eventspace.example.</p><div style="margin-top:30px">${btn('Связаться с командой','#/contacts','outline')}</div></div></main>`}
function design(){return `<main class="container">${pageTop('Дизайн-система EventSpace','Тёплая редакционная эстетика и спокойный, предсказуемый интерфейс.','Дизайн-система')}<section class="section"><span class="eyebrow">01 / ВИЗУАЛЬНАЯ КОНЦЕПЦИЯ</span><h2>Место для важных моментов.</h2><p style="max-width:700px;margin-top:20px">Палитра природных оттенков, выразительные заголовки с засечками и крупные фотографии. Оливковый объединяет навигацию и основные действия, терракотовый выделяет редакционные детали.</p><div class="tokens">${[['Молочный','#FBFAF6','#263229'],['Оливковый','#46523B','#fff'],['Чернильный','#263229','#fff'],['Терракота','#AD5C42','#fff'],['Шалфей','#E9ECDF','#263229']].map(([t,c,fg])=>`<div><div class="swatch" style="background:${c};color:${fg}">${t}</div><p style="font-size:11px;margin-top:7px">${c}</p></div>`).join('')}</div></section><section class="section"><span class="eyebrow">02 / ТИПОГРАФИКА И СЕТКА</span><h2>Ясно. Спокойно. Выразительно.</h2><p style="margin-top:15px">Cormorant Garamond — заголовки. Manrope — интерфейс и основной текст. Шрифты с кириллицей включены в сайт и загружаются локально.</p><div class="compare-scroll"><table class="spec-table"><thead><tr><th>Параметр</th><th>Desktop · 1440</th><th>Tablet · 768</th><th>Mobile · 390</th></tr></thead><tbody>${[['Контейнер','1280 px','720 px','354 px'],['Сетка','12 колонок','8 колонок','4 колонки'],['Поля','80 px','24 px','18 px'],['Промежутки','24 px','18–24 px','16–24 px'],['H1 / H2','64 / 42 px','52 / 35 px','43 / 32 px'],['Текст / подписи','15 / 12 px','15 / 12 px','14 / 11 px'],['Секции','72 px','72 px','45 px']].map(row=>`<tr>${row.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p style="margin-top:20px;font-size:13px">Базовый шаг отступов: 4 px. Радиусы: 8 px для полей, 12–16 px для карточек, 22 px для обложек. Основные кнопки — от 48 px в высоту.</p></section><section class="section"><span class="eyebrow">03 / ЭЛЕМЕНТЫ УПРАВЛЕНИЯ</span><h2>Одна система для всего сайта</h2><div class="component-row"><button class="btn" data-action="demo-toast">Основное действие ${ic('arrow')}</button><button class="btn light" data-action="demo-toast">Вторичное действие</button><button class="btn outline" disabled>Недоступно</button><button class="icon-btn selected" aria-label="Выбрано" data-action="demo-toast">${ic('heart')}</button><span class="badge">Новое место</span><span class="badge ad">TOP · Реклама</span></div><div class="grid3"><div class="field"><label for="ds-input">Обычное поле</label><input class="input" id="ds-input" placeholder="Введите значение"></div><div class="field"><label for="ds-select">Выпадающий список</label>${customSelect('ds-select','city',cities,designSelection,'Выберите город',false,'design')}</div><div class="field"><label for="ds-error">Ошибка валидации</label><input class="input" id="ds-error" aria-invalid="true" aria-describedby="ds-error-text" value="Неверный адрес" style="border-color:var(--accent)"><small id="ds-error-text" style="color:var(--accent)">Введите корректный email</small></div></div><div class="component-row"><label class="check"><input type="checkbox" checked>Выбрано</label><label class="check"><input type="checkbox">Не выбрано</label><label class="check"><input type="checkbox" disabled>Недоступно</label><label class="check"><input type="checkbox" class="toggle" checked>Только различия</label><button class="chip active">Активный фильтр ${ic('close')}</button><button class="chip">Обычный фильтр</button></div><label for="ds-range">Диапазон цены</label><input class="range" id="ds-range" type="range" style="max-width:350px;display:block;margin-top:15px"><div class="component-row"><button class="btn outline" data-action="design-modal">Модальное окно</button><button class="btn outline" data-action="demo-toast">Уведомление</button><a class="btn outline" href="#/states">Пустые состояния</a></div><div class="component-row">${btn('Каталог с активными фильтрами','#/catalog?event='+encodeURIComponent('Свадьба')+'&price=200','outline')}</div><p style="font-size:13px">Наведение: более тёмная заливка / граница. Активное: изменение фона и подписи. Фокус: контрастная обводка 2 px. Неактивное: сниженная насыщенность. Ошибка: терракотовая граница и текстовая подсказка. Выбор всегда отражён и текстом.</p></section><section class="section"><span class="eyebrow">04 / КАРТОЧКИ И МЕДИА</span><div class="grid3">${card(venues[0])}${caseCard(cases[0])}${articleCard(articles[0])}</div></section><section class="section"><span class="eyebrow">05 / НАВИГАЦИЯ И АДАПТИВНОСТЬ</span><h2>Публичный сайт без лишних шагов</h2><div class="compare-scroll"><table class="spec-table"><thead><tr><th>Раздел</th><th>Переходы и адаптация</th></tr></thead><tbody><tr><td>Главная → Каталог → Площадка</td><td>Поиск переносит условия в каталог. Мобильные фильтры открываются в панели.</td></tr><tr><td>Избранное / Сравнение</td><td>Доступны из шапки и меню. Данные хранятся в браузере без аккаунта.</td></tr><tr><td>Площадка → Контакты</td><td>На desktop — боковой блок, на mobile — закреплённая нижняя панель.</td></tr><tr><td>Сравнение 2–4 пространств</td><td>Горизонтальная прокрутка, закреплённый столбец характеристик.</td></tr><tr><td>Кейсы / Журнал → Площадка</td><td>Карточки связанных площадок сохраняют путь к контактам.</td></tr><tr><td>Владельцам → Тариф → Заявка</td><td>Короткая форма. В прототипе отправка симулируется.</td></tr></tbody></table></div></section></main>`}
function tray(){return comp.length&&route().split('?')[0]!=='/compare'&&!route().startsWith('/venue/')?`<aside class="compare-tray" aria-label="Выбранные пространства"><div class="tray-thumbs">${comp.map(findSpace).filter(Boolean).map(r=>image(r.photo,r.name)).join('')}</div><div><strong>${comp.length} из 4 пространств</strong><br><small>${comp.length<2?'Добавьте ещё одно':'Все детали рядом'}</small></div><a class="btn peach small" href="#/compare">Сравнить${ic('arrow')}</a><button class="text-btn" data-action="clear-compare" aria-label="Очистить сравнение">${ic('close')}</button></aside>`:''}
function render(scroll=false){closeAmenity();const r=route().split('?')[0],parts=r.split('/').filter(Boolean);let body,title;
if(r==='/'){body=home();title='Место для вашего события'}else if(r==='/catalog'){body=catalog();title='Каталог площадок'}else if(parts[0]==='venue'){body=parts[2]==='space'?spacePage(parts[1],parts[3]):venuePage(parts[1]);title=parts[2]==='space'?(findSpace(parts[3])?.name||'Пространство'):venue(parts[1]).name}else if(r==='/compare'){body=comparePage();title='Сравнение площадок'}else if(r==='/favorites'){body=favorites();title='Избранное'}else if(r==='/cases'){body=casesPage();title='Кейсы мероприятий'}else if(parts[0]==='cases'){body=casePage(parts[1]);title='История события'}else if(r==='/journal'){body=journal();title='Журнал'}else if(parts[0]==='journal'){body=articlePage(parts[1]);title='Журнал'}else if(r==='/owners'){body=owners();title='Разместить площадку'}else if(r==='/pricing'){body=pricing();title='Тарифы'}else if(r==='/about'){body=about();title='О проекте'}else if(r==='/contacts'){body=contacts();title='Контакты'}else if(r==='/states'){body=states();title='Состояния интерфейса'}else if(r==='/design'){body=design();title='Дизайн-система'}else if(parts[0]==='legal'){body=legal(parts[1]);title='Правовая информация'}else{body=notFound();title='Страница не найдена'}
document.body.classList?.toggle('home-page',true);document.body.classList?.toggle('is-home',r==='/');$('#app').innerHTML=header()+body+footer()+tray();document.title=title+' — EventSpace';if(scroll)window.scrollTo(0,0);startHeroCarousel();
}
function closeModal(){$('#overlay').innerHTML='';document.body.style.overflow='';if(window.lastFocus&&document.contains(window.lastFocus))window.lastFocus.focus()}
function modal(html,cls=''){window.lastFocus=document.activeElement;$('#overlay').innerHTML=`<div class="modal-backdrop" data-backdrop="true"><div class="modal ${cls}" role="dialog" aria-modal="true" aria-label="${cls==='gallery-modal'?'Фотогалерея':'Информация'}"><button class="icon-btn modal-close" data-action="close-modal" aria-label="Закрыть">${ic('close')}</button>${html}</div></div>`;document.body.style.overflow='hidden';$('#overlay button')?.focus()}
function gallery(){modal(`<img src="assets/${galleryImages[galleryIndex]}.jpg" alt="Фото площадки ${galleryIndex+1}"><div class="gallery-controls"><button class="icon-btn" data-action="gallery-prev" aria-label="Предыдущее фото">${ic('back')}</button><span>${galleryIndex+1} / ${galleryImages.length} · Иллюстративные фотографии</span><button class="icon-btn" data-action="gallery-next" aria-label="Следующее фото">${ic('arrow')}</button></div>`,'gallery-modal')}
function openDrawer(type){window.lastFocus=document.activeElement;$('#overlay').innerHTML=`<div class="modal-backdrop" data-backdrop="true"><div class="drawer ${type==='filters'?'filters-drawer':''}" role="dialog" aria-modal="true" aria-label="${type==='filters'?'Фильтры':'Меню'}"><button class="icon-btn modal-close" data-action="${type==='filters'?'close-filters':'close-modal'}" aria-label="Закрыть">${ic('close')}</button>${type==='filters'?filterPanel('-mobile'):`<a class="logo" href="#/">Event<span>Space</span></a><nav>${[['Каталог площадок','/catalog'],['Кейсы мероприятий','/cases'],['Журнал','/journal'],['Избранное','/favorites'],['Сравнение','/compare'],['Разместить площадку','/owners'],['Тарифы','/pricing'],['О проекте','/about'],['Контакты','/contacts'],['Дизайн-система','/design'],['Состояния интерфейса','/states']].map(([t,u])=>`<a href="#${u}">${t}${ic('arrow')}</a>`).join('')}</nav>`}</div></div>`;document.body.style.overflow='hidden';$('#overlay button')?.focus()}
function updateFilter(key,value){if(key==='features')filters.features=filters.features.includes(value)?filters.features.filter(f=>f!==value):[...filters.features,value];else filters[key]=value;showCount=6;refreshFilters()}
function resetFilters(){filters=emptyFilters();showCount=6;refreshFilters()}
function keepFocusRender(el){let id=el.id,pos=el.selectionStart;render();let next=document.getElementById(id);next?.focus();try{next?.setSelectionRange(pos,pos)}catch(e){}}
function hasSpaceFilters(){return !!(filters.q||filters.city||filters.district||filters.guests||filters.price<500||filters.events.length||filters.types.length||filters.features.length)}
function matchingSpaces(v){return v.spaces.filter(r=>(!filters.q||(v.name+' '+r.name+' '+r.type).toLowerCase().includes(filters.q.toLowerCase()))&&(!filters.city||v.city===filters.city)&&(!filters.district||v.district===filters.district)&&(!filters.events.length||filters.events.some(e=>r.events.includes(e)))&&(!filters.types.length||filters.types.includes(r.type))&&(!filters.guests||r.capacity<=Number(filters.guests))&&r.price<=Number(filters.price)&&filters.features.every(f=>r.features.includes(f)))}
function preferredSpace(v){const matches=matchingSpaces(v),rs=matches.length?matches:v.spaces;if(sort==='cheap')return [...rs].sort((a,b)=>a.price-b.price)[0];if(sort==='expensive')return [...rs].sort((a,b)=>b.price-a.price)[0];if(sort==='capacity')return [...rs].sort((a,b)=>b.capacity-a.capacity)[0];return rs[0]}
function customSelect(id,key,options,value,placeholder,multiple=false,scope='catalog',name=''){const opts=options.map(x=>Array.isArray(x)?x:[x,x]),selected=multiple?value:[value].filter(Boolean),labels=selected.map(v=>opts.find(x=>x[0]===v)?.[1]).filter(Boolean),display=labels.length?labels[0]+(labels.length>1?' +'+(labels.length-1):''):placeholder;const choices=multiple?opts:[['',placeholder],...opts];return `<div class="custom-select" data-select-id="${id}" data-key="${key}" data-scope="${scope}" data-multiple="${multiple}"><button class="select-toggle ${labels.length?'has-value':''}" type="button" data-action="select-toggle" aria-expanded="false" aria-haspopup="listbox" aria-controls="${id}-options" aria-label="${placeholder}"><span>${esc(display)}</span>${ic('chevron')}</button>${name?selected.map(x=>`<input type="hidden" name="${name}" value="${esc(x)}">`).join(''):''}<div class="select-panel" id="${id}-options" role="listbox" aria-label="${placeholder}" ${multiple?'aria-multiselectable="true"':''} hidden><div class="select-options">${choices.map(([val,label],i)=>`<button type="button" class="select-option ${selected.includes(val)||(!multiple&&!value&&!val)?'is-selected':''}" role="option" id="${id}-option-${i}" aria-selected="${selected.includes(val)||(!multiple&&!value&&!val)}" data-action="select-option" data-value="${esc(val)}"><span>${esc(label)}</span><span class="select-check">${ic('check')}</span></button>`).join('')}</div>${multiple?`<div class="select-footer"><button type="button" data-action="select-clear">Сбросить</button><button type="button" data-action="select-done">Готово${ic('check')}</button></div>`:''}</div></div>`}
function closeSelects(){document.querySelectorAll('.custom-select.is-open').forEach(el=>{el.classList.remove('is-open');el.querySelector('.select-toggle').setAttribute('aria-expanded','false');el.querySelector('.select-panel').hidden=true})}
function openSelect(el){if(!el)return;closeSelects();el.classList.add('is-open');const panel=el.querySelector('.select-panel');panel.hidden=false;el.querySelector('.select-toggle').setAttribute('aria-expanded','true');const rect=el.getBoundingClientRect();el.classList.toggle('open-up',rect.bottom+Math.min(panel.scrollHeight,320)>window.innerHeight&&rect.top>320)}
function refreshFilters(reopen=''){const drawer=!!$('#overlay .filters-drawer');render();if(drawer){$('#overlay .filter-panel').outerHTML=filterPanel('-mobile')}if(reopen)openSelect(document.querySelector(`[data-select-id="${reopen}"]`))}
function focusSelectValue(id,value){const el=document.querySelector(`[data-select-id="${id}"]`);if(!el)return;openSelect(el);const option=[...el.querySelectorAll('[role="option"]')].find(x=>x.dataset.value===value);(option||el.querySelector('.select-toggle')).focus()}
function changeSelect(el,val,clear=false){const {key,scope,selectId}=el.dataset,multi=el.dataset.multiple==='true';let current=scope==='home'?homeSelection[key]:scope==='catalog'?filters[key]:scope==='sort'?sort:scope==='case'?caseGuests:scope==='design'?designSelection:'';let next=multi?(clear?[]:current.includes(val)?current.filter(x=>x!==val):[...current,val]):(clear?'':val);if(scope==='home'){homeSelection[key]=next;const fresh=customSelect(selectId,key,key==='events'?eventTypes:cities,next,key==='events'?'Любое событие':'Любой город',multi,'home',key==='events'?'event':'city');el.outerHTML=fresh;if(multi)focusSelectValue(selectId,val);else document.querySelector(`[data-select-id="${selectId}"] .select-toggle`)?.focus()}else if(scope==='catalog'){filters[key]=next;showCount=6;refreshFilters(multi?selectId:'');if(multi)focusSelectValue(selectId,val);else document.querySelector(`[data-select-id="${selectId}"] .select-toggle`)?.focus()}else if(scope==='sort'){sort=next||'recommended';render()}else if(scope==='case'){caseGuests=next;render()}else if(scope==='design'){designSelection=next;render()}else closeSelects()}
function heroMarkup(){const slides=['oran','loft','hall','terrace'];return `<div class="hero-slide-stack">${slides.map((id,i)=>{const v=venue(id);return `<div class="hero-slide" ${i===heroIndex?'':'hidden'} aria-roledescription="слайд" aria-label="${i+1} из ${slides.length}"><a class="editorial-photo" href="#/venue/${id}" aria-label="Посмотреть ${v.name}"><img src="assets/${v.photo}.jpg" alt="${v.name} — иллюстрация площадки" ${i===0?'fetchpriority="high" loading="eager"':'loading="lazy"'}><span class="editorial-photo-index">0${i+1} / МЕСТА С ХАРАКТЕРОМ</span></a><a class="editorial-photo-card" href="#/venue/${id}"><span class="editorial-photo-card-icon">${ic(i===0?'leaf':i===1?'spark':'guests')}</span><span><small>${v.spaces.length} ${v.spaces.length===1?'ПРОСТРАНСТВО':'ПРОСТРАНСТВА'}</small><strong>${v.name}</strong><span>${v.city} · ${v.spaces.map(r=>r.name).slice(0,2).join(' и ')}</span></span><span class="editorial-photo-card-arrow">${ic('arrow')}</span></a></div>`}).join('')}</div><div class="hero-controls"><button class="icon-btn" data-action="hero-prev" aria-label="Предыдущая площадка">${ic('back')}</button><div class="hero-dots">${slides.map((id,i)=>`<button data-action="hero-go" data-index="${i}" class="${i===heroIndex?'active':''}" aria-label="Показать ${venue(id).name}" aria-pressed="${i===heroIndex}"></button>`).join('')}</div><button class="hero-pause" data-action="hero-pause" aria-label="${heroPaused?'Включить':'Остановить'} автоматическую смену" aria-pressed="${heroPaused}">${heroPaused?'Продолжить':'Пауза'}</button><button class="icon-btn" data-action="hero-next" aria-label="Следующая площадка">${ic('arrow')}</button></div><span id="hero-status" class="sr-only" role="status" aria-live="polite"></span>`}
function changeHero(index,manual=true){heroIndex=(index+4)%4;const slider=$('#hero-slider');if(!slider)return;slider.innerHTML=heroMarkup();if(manual){$('#hero-status').textContent='Площадка '+(heroIndex+1)+' из 4';slider.querySelector(`[data-action="hero-go"][data-index="${heroIndex}"]`)?.focus()}}
function startHeroCarousel(){clearInterval(heroTimer);if(route().split('?')[0]!=='/')return;if(window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)heroPaused=true;heroTimer=setInterval(()=>{if(heroPaused||document.hidden||$('#hero-slider:hover')||$('#hero-slider:focus-within')||$('.custom-select.is-open'))return;changeHero(heroIndex+1,false)},6500)}
function spaceCard(r,matched=false){return `<article class="space-card ${matched?'matches':''}"><a class="space-card-photo" href="${spaceUrl(r)}">${image(r.photo,r.name)}</a><div class="space-card-body"><div class="space-card-heading"><span class="eyebrow">${r.whole?'ВСЯ ПЛОЩАДКА':r.type}</span>${matched?'<span class="badge">Подходит вам</span>':''}</div><a href="${spaceUrl(r)}"><h3>${r.name}</h3></a><div class="space-facts"><span>${ic('guests')}до ${r.capacity} гостей</span><span>${ic('area')}${r.area} м²</span></div><p>${r.whole?'Все залы в одной аренде':'Отдельное пространство площадки'}</p><div class="space-card-bottom"><span class="price">от ${r.price} <small>BYN / час</small></span>${btn('Подробнее',spaceUrl(r),'light small')}</div><button class="compare-btn ${comp.includes(r.id)?'on':''}" data-action="compare" data-id="${r.id}" aria-pressed="${comp.includes(r.id)}">${ic(comp.includes(r.id)?'check':'compare')}${comp.includes(r.id)?'В сравнении':'Сравнить пространство'}</button></div></article>`}
function galleryMarkup(v,r=null){const entity=r||v;return `<div class="gallery">${galleryFor(entity).map((im,i)=>`<button data-action="gallery" data-id="${v.id}" ${r?`data-room="${r.id}"`:''} data-index="${i}" aria-label="Открыть фото ${i+1}">${image(im,entity.name+' · фото '+(i+1))}</button>`).join('')}<button class="gallery-all" data-action="gallery" data-id="${v.id}" ${r?`data-room="${r.id}"`:''} data-index="0">${ic('grid')}Все фотографии</button></div>`}
function mobileContact(v,r=null){return `<div class="mobile-contact"><div><small>${r?r.name:'Пространства площадки'}</small><span class="price">от ${r?r.price:Math.min(...v.spaces.map(x=>x.price))} <small>BYN / час</small></span></div><button class="btn" data-action="contact" data-id="${v.id}" ${r?`data-room="${r.id}"`:''}>${ic('phone')}Связаться</button></div>`}
function spacePage(venueId,roomId,single=false){const v=venues.find(x=>x.id===venueId),r=findSpace(roomId);if(!v||!r||r.venueId!==v.id)return notFound();return `<main class="detail-page space-page"><div class="container"><div class="page-top"><div class="breadcrumbs"><a href="#/">Главная</a> / <a href="#/catalog">Площадки</a> / ${single?v.name:`<a href="#/venue/${v.id}">${v.name}</a> / ${r.name}`}</div><span class="eyebrow">${r.whole?'ВСЯ ПЛОЩАДКА':r.type} · ${v.city}</span><div class="title-row"><h1>${single?v.name:r.name}</h1><div class="title-actions"><button class="icon-btn ${saved.includes(v.id)?'selected':''}" data-action="favorite" data-id="${v.id}" aria-label="Сохранить площадку" aria-pressed="${saved.includes(v.id)}">${ic('heart')}</button><button class="icon-btn ${comp.includes(r.id)?'selected':''}" data-action="compare" data-id="${r.id}" aria-label="Сравнить пространство" aria-pressed="${comp.includes(r.id)}">${ic('compare')}</button></div></div><p class="venue-address">${ic('pin')}${v.address}${!single?` · <a href="#/venue/${v.id}">${v.name} ↗</a>`:''}</p></div>${galleryMarkup(v,r)}<div class="detail-layout"><div class="detail-content"><div class="facts"><div><strong>до ${r.capacity}</strong><small>гостей</small></div><div><strong>${r.area} м²</strong><small>площадь</small></div><div><strong>от ${r.price} BYN</strong><small>за час этого пространства</small></div></div><section><h2>${r.whole?'Всё место — для вашего события':'Пространство для вашей идеи'}</h2><p>${single?(v.desc||r.description):r.description}</p><p class="section-description">${r.name} · ${v.name}. У этого пространства свои условия и оснащение. Представитель поможет подобрать расстановку под ваш формат.</p><div class="card-tags">${r.events.map(e=>`<span>${e}</span>`).join('')}</div></section><section><h2>Что есть в пространстве</h2><p class="amenities-hint">Наведите на пункт или нажмите, чтобы узнать подробности.</p><div class="amenities amenities-interactive">${[...r.features,'Мебель для гостей','Естественное освещение'].map((f,i)=>amenityItem(r,f,i)).join('')}</div></section><section><h2>Варианты рассадки</h2><div class="seating-options"><div>${ic('food')}<strong>${Math.floor(r.capacity*.75)}</strong><span>банкет</span></div><div>${ic('conference')}<strong>${r.capacity}</strong><span>театр / фуршет</span></div><div>${ic('business')}<strong>${Math.floor(r.capacity*.5)}</strong><span>деловая встреча</span></div></div><p class="field-help">Варианты иллюстративные. Точную схему согласуйте с представителем.</p></section><section><h2>Условия этого пространства</h2><div class="amenities"><div>${ic('check')}Аренда от 3 часов</div><div>${ic('check')}Монтаж по договорённости</div><div>${ic('info')}Курение только на улице</div><div>${ic('info')}Музыка до 23:00</div></div><p class="section-description">Уточните, включены ли настройка техники, уборка и время подготовки в стоимость. Правила использования общих зон обсуждаются отдельно.</p></section><section><h2>Площадка и расположение</h2><a class="venue-parent-link" href="#/venue/${v.id}"><span>${v.name}<small>${v.city} · ${v.spaces.length} ${v.spaces.length===1?'пространство':'пространства'} · ${v.company}</small></span>${ic('arrow')}</a>${mapMarkup([v])}</section>${r.cases?`<section><h2>События в этом пространстве</h2><div class="grid2">${cases.filter(c=>c.venue===v.id).map(caseCard).join('')}</div></section>`:''}</div>${contactBlock(v,r)}</div>${v.spaces.length>1?`<section class="section">${sectionHead('Другие пространства этой площадки','Тот же адрес — другой сценарий.')}<div class="space-list compact">${v.spaces.filter(x=>x.id!==r.id).map(x=>spaceCard(x)).join('')}</div></section>`:`<section class="section">${sectionHead('Похожие места','','#/catalog','В каталог')}<div class="grid3">${venues.filter(x=>x.id!==v.id).slice(0,3).map(card).join('')}</div></section>`}</div>${mobileContact(v,r)}</main>`}
function contactModal(venueId,roomId=''){const v=venue(venueId),r=findSpace(roomId);modal(`<span class="eyebrow">СВЯЗЬ НАПРЯМУЮ</span><h2>${v.name}</h2>${r?`<div class="contact-selected-space">${ic('area')}<div><small>Вас интересует пространство</small><strong>${r.name}</strong><span>До ${r.capacity} гостей · от ${r.price} BYN / час</span></div></div>`:'<p>Представитель поможет подобрать пространство и расскажет об условиях аренды.</p>'}<div class="contact-person"><span class="avatar">А</span><div>Анна · представитель<br><small>${v.company}</small></div></div><button class="btn full" data-action="contact-channel" data-channel="Телефон">${ic('phone')}+375 (00) 000-00-00</button><button class="btn light full" data-action="contact-channel" data-channel="Telegram" style="margin-top:10px">${ic('send')}Написать в Telegram</button><button class="btn light full" data-action="contact-channel" data-channel="Сайт площадки" style="margin-top:10px">${ic('web')}venue.example</button><p class="demo-note" style="margin-top:20px">Контакты вымышлены. В рабочей версии дату и условия вы согласуете напрямую.</p>`)}

document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(!a){if(e.target.dataset.backdrop){const isFilter=!!$('#overlay .filters-drawer');closeModal();if(isFilter)render()}return}const act=a.dataset.action,id=a.dataset.id;
if(act==='select-toggle'){const el=a.closest('.custom-select');if(el.classList.contains('is-open'))closeSelects();else openSelect(el);return}
if(act==='select-option'){changeSelect(a.closest('.custom-select'),a.dataset.value);return}
if(act==='select-clear'){changeSelect(a.closest('.custom-select'),'',true);return}
if(act==='select-done'){const el=a.closest('.custom-select');closeSelects();el.querySelector('.select-toggle').focus();return}
if(act==='remove-multi-filter'){filters[a.dataset.key]=filters[a.dataset.key].filter(x=>x!==id);render();return}
if(act==='hero-next'){changeHero(heroIndex+1);return}if(act==='hero-prev'){changeHero(heroIndex-1);return}if(act==='hero-go'){changeHero(Number(a.dataset.index));return}if(act==='hero-pause'){heroPaused=!heroPaused;changeHero(heroIndex,false);$('#hero-slider [data-action="hero-pause"]')?.focus();return}
if(act==='scroll-section'){$('#'+id)?.scrollIntoView({behavior:'smooth'});return}

if(act==='amenity-info'){if(amenityOpen?.trigger===a&&amenityOpen.pinned)closeAmenity();else showAmenity(a,true);return}
if(act==='favorite'){saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];persist();render();toast(saved.includes(id)?'Площадка сохранена в избранное':'Площадка удалена из избранного')}
if(act==='compare'){if(!findSpace(id))return;if(comp.includes(id)){comp=comp.filter(x=>x!==id)}else{if(comp.length>=4){toast('Можно сравнить до четырёх пространств. Уберите одно из выбранных.');return}comp.push(id)}persist();render();toast(comp.includes(id)?'Пространство добавлено в сравнение':'Пространство убрано из сравнения')}
if(act==='clear-compare'){comp=[];persist();render();toast('Список сравнения очищен')}
if(act==='clear-favorites'){saved=[];persist();render();toast('Избранное очищено')}
if(act==='menu')openDrawer('menu');if(act==='filters')openDrawer('filters');if(act==='close-filters'){closeModal();render()}if(act==='close-modal')closeModal();
if(act==='reset-filters')resetFilters();if(act==='remove-filter'){filters[a.dataset.key]=a.dataset.key==='price'?500:'';render()}if(act==='remove-feature'){filters.features=filters.features.filter(f=>f!==id);render()}
if(act==='view-map'){mapView=true;render()}if(act==='view-list'){mapView=false;render()}if(act==='load-more'){showCount=venues.length;render()}
if(act==='map-preview'){const v=venue(id),r=preferredSpace(v);$('#map-preview').innerHTML=`<div class="map-preview">${image(r.photo,v.name)}<a href="#/venue/${id}"><strong>${v.name}</strong><br>${r.name} · до ${r.capacity} гостей<br>от ${r.price} BYN / час ${ic('arrow')}</a></div>`}
if(act==='gallery'){const v=a.dataset.room?findSpace(a.dataset.room):venue(id);galleryImages=galleryFor(v);galleryIndex=Number(a.dataset.index)||0;gallery()}if(act==='gallery-prev'){galleryIndex=(galleryIndex+galleryImages.length-1)%galleryImages.length;gallery()}if(act==='gallery-next'){galleryIndex=(galleryIndex+1)%galleryImages.length;gallery()}
if(act==='contact')contactModal(id,a.dataset.room);
if(act==='contact-channel')toast(`${a.dataset.channel}: демонстрационный контакт, переход отключён`);
if(act==='case-filter'){caseFilter=id;render()}if(act==='reset-cases'){caseFilter='';caseGuests='';render()}if(act==='journal-filter'){journalFilter=id;render()}if(act==='reset-journal'){journalFilter='';journalQuery='';render()}
if(act==='state'){stateView=id;render()}if(act==='retry'){stateView='success';render()}
if(act==='demo-toast')toast('Так выглядит уведомление EventSpace');if(act==='design-modal')modal(`<span class="eyebrow">КОМПОНЕНТ / МОДАЛЬНОЕ ОКНО</span><h2>Всё важное — в фокусе</h2><p>Заголовок объясняет действие, текст помогает принять решение. Окно закрывается кнопкой, по Escape или нажатием на фон.</p><button class="btn" data-action="close-modal">Понятно ${ic('check')}</button>`);
if(act==='scroll-application')$('#application')?.scrollIntoView({behavior:'smooth'});
});
document.addEventListener('input',e=>{if(e.target.id==='search-guests')homeSelection.guests=e.target.value;if(e.target.id==='catalog-query'){filters.q=e.target.value;showCount=6;keepFocusRender(e.target)}if(e.target.id==='journal-query'){journalQuery=e.target.value;keepFocusRender(e.target)}});
document.addEventListener('change',e=>{if(e.target.dataset.filter)updateFilter(e.target.dataset.filter,e.target.value);if(e.target.id==='sort'){sort=e.target.value;render()}if(e.target.id==='differences'){differences=e.target.checked;render()}if(e.target.id==='case-guests'){caseGuests=e.target.value;render()}});
document.addEventListener('submit',e=>{if(e.target.id==='home-search'){e.preventDefault();const d=new FormData(e.target);filters={...emptyFilters(),events:d.getAll('event').filter(x=>eventTypes.includes(x)),city:d.get('city')||'',guests:d.get('guests')||''};showCount=6;location.hash='/catalog'}if(e.target.matches('.demo-form')){e.preventDefault();const f=e.target;if(f.dataset.form==='owner'){const c=f.elements.contact;const val=c.value.trim();if(!/^@\w{4,}$/.test(val)&&! /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val)){c.setCustomValidity('Введите email или Telegram в формате @username');c.reportValidity();c.addEventListener('input',()=>c.setCustomValidity(''),{once:true});return}}const b=f.querySelector('[type="submit"]');b.disabled=true;b.textContent='Отправляем…';setTimeout(()=>{if(!document.contains(f))return;f.innerHTML=`<div class="empty" style="min-height:380px;padding:25px 0"><span class="empty-symbol">${ic('check')}</span><h2>${f.dataset.form==='owner'?'Спасибо! Мы познакомились.':'Спасибо за ваше сообщение.'}</h2><p>Сценарий отправки успешно завершён. Это прототип: данные не отправлены и не сохранены.</p><a class="btn outline" href="#/">На главную ${ic('arrow')}</a></div>`;f.scrollIntoView({behavior:'smooth',block:'center'})},750)}});
document.addEventListener('keydown',e=>{const select=e.target.closest?.('.custom-select');if(e.key==='Escape'&&$('.custom-select.is-open')){const open=$('.custom-select.is-open');closeSelects();open.querySelector('.select-toggle').focus();return}if(select&&['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();openSelect(select);const options=[...select.querySelectorAll('[role="option"]')];let index=options.indexOf(document.activeElement);index=e.key==='Home'?0:e.key==='End'?options.length-1:(index+(e.key==='ArrowDown'?1:-1)+options.length)%options.length;options[index]?.focus();return}if(e.key==='Escape'&&amenityOpen){closeAmenity();return}if(!$('#overlay').innerHTML)return;if(e.key==='Escape'){const wasFilter=!!$('#overlay .filters-drawer');closeModal();if(wasFilter)render()}if(e.key==='ArrowRight'&&$('#overlay .gallery-modal')){galleryIndex=(galleryIndex+1)%galleryImages.length;gallery()}if(e.key==='ArrowLeft'&&$('#overlay .gallery-modal')){galleryIndex=(galleryIndex+galleryImages.length-1)%galleryImages.length;gallery()}if(e.key==='Tab'){const fs=[...$('#overlay').querySelectorAll('button,a,input,select,textarea')].filter(x=>!x.disabled);if(!fs.length)return;const first=fs[0],last=fs[fs.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
function navigate(){closeModal();closeSelects();const r=route();if(r.startsWith('/catalog?')){filters=emptyFilters();const p=new URLSearchParams(r.split('?')[1]);filters.events=p.getAll('event').filter(x=>eventTypes.includes(x));filters.types=p.getAll('type').filter(x=>venueTypes.includes(x));if(p.has('city'))filters.city=cities.includes(p.get('city'))?p.get('city'):'';if(p.has('district'))filters.district=p.get('district');if(p.has('guests'))filters.guests=String(Math.max(1,Number(p.get('guests'))||1));if(p.has('price'))filters.price=Math.max(50,Math.min(500,Number(p.get('price'))||500));if(p.has('sort'))sort=['recommended','cheap','expensive','capacity','new'].includes(p.get('sort'))?p.get('sort'):'recommended';showCount=6}render(true);if(r.startsWith('/owners?'))requestAnimationFrame(()=>$('#application')?.scrollIntoView())}
document.addEventListener('pointerdown',e=>{if(!e.target.closest('.custom-select'))closeSelects()});document.addEventListener('focusin',e=>{const open=$('.custom-select.is-open');if(open&&!open.contains(e.target))closeSelects()});
window.addEventListener('hashchange',navigate);navigate();
